CREATE DATABASE IF NOT EXISTS student_finance CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE student_finance;

CREATE TABLE IF NOT EXISTS users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS categories (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,name VARCHAR(80) NOT NULL,need_want ENUM('Need','Want') NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_category_user_name(user_id,name),CONSTRAINT fk_categories_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS category_rules (rule_id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,merchant_keyword VARCHAR(120) NOT NULL,category_id INT UNSIGNED NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_category_rule_keyword(user_id,merchant_keyword),INDEX ix_category_rules_category(category_id),CONSTRAINT fk_category_rules_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_category_rules_category FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS incomes (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,source VARCHAR(120) NOT NULL,amount DECIMAL(12,2) NOT NULL,income_type ENUM('Recurring','One-time') NOT NULL DEFAULT 'One-time',frequency ENUM('Weekly','Monthly','Yearly','N/A') NOT NULL DEFAULT 'N/A',start_date DATE NOT NULL,status ENUM('Active','Inactive') NOT NULL DEFAULT 'Active',income_date DATE NOT NULL,description VARCHAR(500) NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX ix_income_user_date(user_id,income_date),INDEX ix_income_user_status(user_id,status),CONSTRAINT fk_incomes_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS transactions (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,category_id INT UNSIGNED NULL,type ENUM('Income','Expense') NOT NULL,amount DECIMAL(12,2) NOT NULL,description VARCHAR(500) NULL,merchant VARCHAR(120) NULL,transaction_date DATE NOT NULL,source ENUM('Manual','Receipt','Import') NOT NULL DEFAULT 'Manual',import_reference VARCHAR(100) NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX ix_transactions_user_date(user_id,transaction_date),INDEX ix_transactions_user_type(user_id,type),INDEX ix_transactions_category(category_id),UNIQUE KEY uq_transactions_import_reference(user_id,import_reference),CONSTRAINT fk_transactions_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_transactions_category FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS receipt_uploads (receipt_id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,stored_name VARCHAR(100) NOT NULL,original_name VARCHAR(255) NOT NULL,mime_type VARCHAR(50) NOT NULL,file_size INT UNSIGNED NOT NULL,ocr_text MEDIUMTEXT NULL,ocr_status ENUM('Pending','Completed','Unavailable','Failed') NOT NULL DEFAULT 'Pending',ocr_engine VARCHAR(50) NULL,ocr_confidence DECIMAL(5,2) NULL,detected_merchant VARCHAR(120) NULL,detected_amount DECIMAL(12,2) NULL,detected_date DATE NULL,transaction_id INT UNSIGNED NULL,confirmed_at DATETIME NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_receipt_stored_name(stored_name),UNIQUE KEY uq_receipt_transaction(transaction_id),INDEX ix_receipts_user_created(user_id,created_at),CONSTRAINT fk_receipts_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_receipts_transaction FOREIGN KEY(transaction_id) REFERENCES transactions(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS budgets (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,category_id INT UNSIGNED NULL,category_key INT UNSIGNED AS (IFNULL(category_id,0)) PERSISTENT,budget_amount DECIMAL(12,2) NOT NULL,budget_month CHAR(7) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_budget_scope(user_id,budget_month,category_key),CONSTRAINT fk_budgets_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_budgets_category FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE RESTRICT,CONSTRAINT chk_budget_positive CHECK(budget_amount>0)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS savings_goals (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,goal_name VARCHAR(150) NOT NULL,goal_type ENUM('Monthly','Target') NOT NULL DEFAULT 'Target',target_amount DECIMAL(12,2) NOT NULL,current_amount DECIMAL(12,2) NOT NULL DEFAULT 0,target_date DATE NULL,description VARCHAR(500) NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX ix_goals_user_type(user_id,goal_type),CONSTRAINT fk_goals_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT chk_goal_target_positive CHECK(target_amount>0),CONSTRAINT chk_goal_current_nonnegative CHECK(current_amount>=0)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS split_bills (split_bill_id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,total_amount DECIMAL(12,2) NOT NULL,description VARCHAR(180) NOT NULL,bill_date DATE NOT NULL,split_type ENUM('Equal','Custom') NOT NULL DEFAULT 'Equal',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX ix_split_bills_user_date(user_id,bill_date),CONSTRAINT fk_split_bills_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT chk_split_bill_total_positive CHECK(total_amount>0)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS split_bill_participants (participant_id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,split_bill_id INT UNSIGNED NOT NULL,name VARCHAR(80) NOT NULL,share_amount DECIMAL(12,2) NOT NULL,status ENUM('Paid','Pending') NOT NULL DEFAULT 'Pending',paid_at DATETIME NULL,is_owner TINYINT(1) NOT NULL DEFAULT 0,is_payer TINYINT(1) NOT NULL DEFAULT 0,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX ix_split_participants_bill_status(split_bill_id,status),CONSTRAINT fk_split_participants_bill FOREIGN KEY(split_bill_id) REFERENCES split_bills(split_bill_id) ON DELETE CASCADE,CONSTRAINT chk_split_share_nonnegative CHECK(share_amount>=0)) ENGINE=InnoDB;
